import{_ as a,o as t,c as n,ai as o}from"./chunks/framework.hQYAQKfW.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"HelpCenter/Soucing-Order-Payment.md","filePath":"HelpCenter/Soucing-Order-Payment.md"}'),r={name:"HelpCenter/Soucing-Order-Payment.md"};function s(i,e,c,d,p,l){return t(),n("div",null,[...e[0]||(e[0]=[o('<h3 id="_1-sourcing" tabindex="-1">1. Sourcing <a class="header-anchor" href="#_1-sourcing" aria-label="Permalink to “1. Sourcing”">​</a></h3><p>You can search by keywords or paste an image URL on the product search page, also can search by Image.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773389619655-3e46e5a2-02da-4a5f-9a13-fdf3e11a888f.png" alt="1773389619655 3e46e5a2 02da 4a5f 9a13 fdf3e11a888f"></p><p>After entering the search list page, you can sort by sales volume and price. Click on the product to enter the product detail page and view more detailed information about the item.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773392144041-a8ac02ae-3ae7-4a19-9ed7-67def3ed1fba.png" alt="1773392144041 a8ac02ae 3ae7 4a19 9ed7 67def3ed1fba"></p><p>Contents and Icon Definitions：</p><p><strong>11,000 sold</strong> : means this product has been sold 11,000 units in the recent 30 days.</p><p><strong>Repeat Pruchase Rate:</strong> the percentage of repeat customers to total customers.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773403363808-f06a6668-47ed-4c59-97d8-a87a0950b9f9.png" alt="1773403363808 f06a6668 47ed 4c59 97d8 a87a0950b9f9"><strong>Super Factory:</strong> The highest membership level on the 1688 platform, referring to large-scale manufacturers with strong production capacity and technical strength. They are usually industry leaders, enterprises above designated size, or specialized and sophisticated enterprises. They focus on displaying production equipment, manufacturing processes, and quality control, and provide large-scale customized production services.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773403468955-928dce60-9aaf-41df-9701-7ab70ac95606.png" alt="1773403468955 928dce60 9aaf 41df 9701 7ab70ac95606"><strong>Qualified Factory:</strong> Refers to small and medium-sized manufacturers, wholesalers, or traders with a certain scale and commercial reputation. They emphasize stable supply chain resources, product display, and customer service.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773402615123-433bb245-0790-486e-8c58-cbb73a73fe4a.png" alt="1773402615123 433bb245 0790 486e 8c58 cbb73a73fe4a"></p><h3 id="_2-order" tabindex="-1">2. Order <a class="header-anchor" href="#_2-order" aria-label="Permalink to “2. Order”">​</a></h3><p>On the product detail page, you can place an order directly or add the product to the shopping cart. Meanwhile, the procurement cost breakdown of the product is available on the product detail page, including Product Price, Domestic Shipping, International Shipping, and Agent Procurement Service Fee.</p><p>International Shipping Fee can only be calculated after completing the basic product information, destination country, and logistics company and route selection.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773391386537-6208f251-f50c-4dd6-bd23-29512d80cfff.png" alt="1773391386537 6208f251 f50c 4dd6 bd23 29512d80cfff"></p><h3 id="_3-payment" tabindex="-1">3. Payment <a class="header-anchor" href="#_3-payment" aria-label="Permalink to “3. Payment”">​</a></h3><p>Click &quot;Buy Now&quot; enter the order confirmation page. After confirming all information is correct, click &quot;Place Order&quot;, a prompt will appear indicating that the order was submitted successfully.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773391476279-4c3073d4-831c-436e-be70-fab83f68e70e.png" alt="1773391476279 4c3073d4 831c 436e be70 fab83f68e70e"></p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773391571247-3cec4cef-574e-4139-b77d-f901477f5ff5.png" alt="1773391571247 3cec4cef 574e 4139 b77d f901477f5ff5"></p><p>Enter Membership Center &amp; Purchase Order, click &quot;Pay Order&quot; to make payment. Two payment methods are currently supported, PayPal &amp; Bank Transfer.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773391674273-4d2444e6-53fe-49fd-bd7a-14ea8f484460.png" alt="1773391674273 4d2444e6 53fe 49fd bd7a 14ea8f484460"></p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773391941649-30ad8d65-8f3b-4009-9d43-5fde196b3523.png" alt="1773391941649 30ad8d65 8f3b 4009 9d43 5fde196b3523"></p><h3 id="_4-order-status" tabindex="-1">4. Order status <a class="header-anchor" href="#_4-order-status" aria-label="Permalink to “4. Order status”">​</a></h3><p>Possible order status: &quot;Not Started&quot; , &quot;In Progress&quot; , &quot;Completed&quot; , &quot;Cancelled&quot;.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773401844552-27ed7593-5304-49ee-a662-bb051eda1f27.png" alt="1773401844552 27ed7593 5304 49ee a662 bb051eda1f27"></p><p>If you want to know the sub-status,you can click &quot;Fulfillment Sub-status&quot;,there will show more status about the oder, which can let you know more details.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773401568092-40dbfadb-8179-4d0d-93c1-548295e31342.png" alt="1773401568092 40dbfadb 8179 4d0d 93c1 548295e31342"></p>',27)])])}const h=a(r,[["render",s]]);export{m as __pageData,h as default};
